<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {Music2,Play,Pause,FolderOpen} from 'lucide-vue-next'
import {useAudioStore,type AudioTrack} from '@/stores/audio'
import type {VideoItem} from '@/types'
const props=defineProps<{items:VideoItem[]}>(),emit=defineEmits<{open:[item:VideoItem]}>(),audio=useAudioStore()
const tracks=ref<AudioTrack[]>([]),failure=ref('')
let revision=0
watch(()=>props.items,async items=>{const round=++revision;failure.value='';const rows:AudioTrack[]=[];for(const item of items){try{const library=await window.baoyi.video.library(item.id);if(round!==revision)return;if(library.contents.length){for(const ep of library.contents)rows.push({id:ep.id,resource:item,title:ep.title,episode:ep.id,duration:ep.duration_sec})}else rows.push({id:item.id,resource:item,title:item.name_zh||item.file_name,episode:'',duration:item.duration_sec})}catch{if(round===revision)failure.value='部分曲目暂时无法读取，请刷新重试'}}if(round===revision)tracks.value=rows},{immediate:true})
onBeforeUnmount(()=>revision++)
function duration(seconds:number){return seconds?`${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`:'—'}
function play(track:AudioTrack){void audio.play(track,tracks.value)}
</script>
<template><div class="audio-library"><header><div class="audio-disc"><Music2 :size="34"/></div><div><span class="audio-eyebrow">音乐 · 播客 · 有声书</span><h2>我的音频</h2><p>{{items.length}} 个专辑或文件夹 · {{tracks.length}} 首曲目</p></div></header><p v-if="!tracks.length">选择「导入音频」，添加本地专辑、播客或有声书。</p><p v-if="failure" class="audio-error" role="alert">{{failure}}<button v-if="audio.current" @click="emit('open',audio.current.resource)">打开详情</button></p><div class="audio-table"><div class="audio-row audio-head"><span>#</span><span>曲目</span><span>专辑 / 文件夹</span><span>时长</span><span/></div><div v-for="(track,i) in tracks" :key="track.id" class="audio-row" :class="{current:audio.current?.id===track.id}"><button :aria-label="'播放 '+track.title" @click="play(track)"><Pause v-if="audio.current?.id===track.id && audio.playing" :size="15"/><Play v-else-if="audio.current?.id===track.id" :size="15"/><span v-else>{{i+1}}</span></button><button class="audio-name" @click="play(track)">{{track.title}}</button><button class="audio-album" @click="emit('open',track.resource)">{{track.resource.name_zh||track.resource.file_name}}</button><span>{{duration(track.duration)}}</span><button :aria-label="'查看 '+track.title" @click="emit('open',track.resource)"><FolderOpen :size="15"/></button></div></div></div></template>
<style scoped>.audio-library{padding:10px 6px 0}.audio-library>header{display:flex;gap:22px;align-items:center;margin-bottom:30px}.audio-disc{width:94px;height:94px;border-radius:50%;display:grid;place-items:center;border:14px double var(--divider);background:var(--active-surface);color:var(--accent)}.audio-eyebrow{font-size:11px;letter-spacing:2px;color:var(--text-sub)}.audio-library h2{font-size:27px;margin:8px 0}.audio-library p{font-size:12px;color:var(--text-sub)}.audio-table{border-top:1px solid var(--divider);padding-bottom:24px}.audio-row{display:grid;grid-template-columns:35px minmax(180px,2fr) minmax(140px,1fr) 65px 30px;align-items:center;gap:15px;padding:13px 10px;border-bottom:1px solid var(--divider);font-size:13px}.audio-row.current{background:var(--active-surface);color:var(--accent)}.audio-row button{text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.audio-head{font-size:11px;color:var(--text-faint);padding-block:15px}.audio-album,.audio-row>span{color:var(--text-sub)}.audio-name{font-weight:500}.audio-error{color:var(--danger)!important}.audio-error button{margin-left:12px;text-decoration:underline}</style>
